// Decide which session to use: Load session by id result first, else active session result, else created session
const byId = $node['Load session by id'].json[0];
const active = $node['Find active session'].json[0];
const created = $node['Create session'].json[0];
let session = null;
if(byId && byId.id) session = byId;
else if(active && active.id) session = active;
else session = created;
return [{ json: { session_id: session.id, current_step: session.current_step, ai_context: session.ai_context || {} } }];

// Determine next question text based on updated current_step
const step = $node['Save answer and advance'].json[0] ? $node['Save answer and advance'].json[0].current_step : $node['Resolve session'].json[0].current_step;
const questions = [
  'What is your name?',
  'How old are you?',
  'Which city do you live in?',
  'Tell us about yourself (short description)',
  'List your interests (comma separated)',
  'What is your goal on this platform (e.g. dating, friends)?',
  'Optional: any hobbies?',
  'Optional: what is your job?',
  'Optional: education?',
  'Optional: preferred communication style?'
];
const next = questions[step] || null;
return [{ json: { next_question: next, current_step: step } }];

